using System.Reflection;
using System.Runtime.InteropServices;
using OcctSharp.CopiedCollections;
namespace OcctSharp.Runtime.Tests;
public sealed class TopologyExchangeCollectionsTests {
 static readonly int[] UnsupportedLookupModes = [0,2,3,4];
 [Fact]public void CompletePublicOnlyWorkflow()=>OcctSharp.Tests.Shared.BatchAITopologyExchangeWorkflow.Run();
 [Fact]public void OrderedShapeCopiesPreservePartnerLocationOrientationAndDuplicates(){using var shape=ShapeFactory.CreateBox(2,3,4);using var reversed=shape.Reversed();using var tr=GpTrsf.Create(7,0,0,0,0,1,0);using var loc=TopLocLocation.FromTransform(tr);using var moved=shape.Moved(loc);using var set=OwnedShapeSet.Create(reversed,moved,shape,shape);using var a=set.GetShape(0);using var b=set.GetShape(1);using var c=set.GetShape(2);using var d=set.GetShape(3);Assert.Equal(4,set.Count);Assert.True(a.IsEqual(reversed));Assert.True(a.IsSame(shape));Assert.False(a.IsEqual(shape));Assert.True(b.IsEqual(moved));Assert.True(b.IsPartner(shape));Assert.False(b.IsSame(shape));Assert.True(c.IsEqual(d));shape.Dispose();reversed.Dispose();moved.Dispose();set.Dispose();Assert.True(a.IsValid);Assert.True(b.IsValid);Assert.True(c.IsValid);}
 [Fact]public void ShapeSetsRejectNullDisposedAndOutOfRangeInputs(){using var empty=OwnedShapeSet.Create();Assert.Equal(0,empty.Count);Assert.Throws<ArgumentException>(()=>empty.GetShape(0));Assert.Throws<ArgumentNullException>(()=>OwnedShapeSet.Create((Shape)null!));using var shape=ShapeFactory.CreateBox(1,1,1);using var set=OwnedShapeSet.Create(shape);Assert.Throws<ArgumentException>(()=>set.GetShape(-1));Assert.Throws<ArgumentException>(()=>set.GetShape(int.MaxValue));shape.Dispose();Assert.Throws<ObjectDisposedException>(()=>OwnedShapeSet.Create(shape));set.Dispose();Assert.Throws<ObjectDisposedException>(()=>set.GetShape(0));}
 [Theory][InlineData(TopologyCollectionOperation.Fuse)][InlineData(TopologyCollectionOperation.Cut)][InlineData(TopologyCollectionOperation.Common)][InlineData(TopologyCollectionOperation.Split)][InlineData(TopologyCollectionOperation.GeneralFuse)]public void PrivateAlgorithmsPublishIndependentSetsAndShape(TopologyCollectionOperation operation){using var a=ShapeFactory.CreateBox(10,10,10);using var b=a.Transformed(ShapeTransform.CreateTranslation(5,0,0));using var args=operation==TopologyCollectionOperation.GeneralFuse?OwnedShapeSet.Create(a,b):OwnedShapeSet.Create(a);using var tools=operation==TopologyCollectionOperation.GeneralFuse?OwnedShapeSet.Create():OwnedShapeSet.Create(b);using var result=TopologyCollectionResult.Build(args,tools,operation);using var saved=result.Arguments;using var sections=result.SectionEdges;using var shape=result.Shape;if(operation!=TopologyCollectionOperation.GeneralFuse){using var copies=result.Tools;Assert.Equal(1,copies.Count);using var tool=copies.GetShape(0);Assert.True(tool.IsEqual(b));}result.Dispose();args.Dispose();tools.Dispose();a.Dispose();b.Dispose();Assert.True(shape.IsValid);using var input=saved.GetShape(0);Assert.True(input.IsValid);}
 [Fact]public void HistoryRejectsGeometricLookalikesAndPreservesAllNativePaths(){using var a=ShapeFactory.CreateBox(10,10,10);using var b=a.Transformed(ShapeTransform.CreateTranslation(5,0,0));using var args=OwnedShapeSet.Create(a);using var tools=OwnedShapeSet.Create(b);using var result=TopologyCollectionResult.Build(args,tools,TopologyCollectionOperation.Fuse);var faces=a.GetFaces();try{using var modified=result.Modified(faces[0]);using var generated=result.Generated(faces[0]);_ =result.IsDeleted(faces[0]);using var foreign=ShapeFactory.CreateBox(10,10,10);Assert.Throws<ArgumentException>(()=>result.Modified(foreign));Assert.Throws<ArgumentException>(()=>result.Generated(foreign));Assert.Throws<ArgumentException>(()=>result.IsDeleted(foreign));using var shape=result.Shape;for(int i=0;i<modified.Count;++i){using var item=modified.GetShape(i);Assert.True(item.IsValid);Assert.True(RepairSnapshot.FindTopologyIndex(shape,item)>=0);}}finally{foreach(var face in faces)face.Dispose();}}
 [Fact]public void AlgorithmFailuresDoNotPublishOrMutateSourceCollections(){using var empty=OwnedShapeSet.Create();using var shape=ShapeFactory.CreateBox(2,2,2);using var args=OwnedShapeSet.Create(shape);Assert.Throws<ArgumentException>(()=>TopologyCollectionResult.Build(empty,args,TopologyCollectionOperation.Fuse));Assert.Throws<ArgumentException>(()=>TopologyCollectionResult.Build(args,empty,TopologyCollectionOperation.Fuse));Assert.Throws<ArgumentException>(()=>TopologyCollectionResult.Build(args,args,(TopologyCollectionOperation)99));Assert.Equal(1,args.Count);Assert.True(shape.IsValid);}
 [Fact]public void DefeaturingRetainsFacesAndExactHistory(){using var box=ShapeFactory.CreateBox(10,10,10);using var rawBoss=ShapeFactory.CreateBox(2,2,2);using var boss=rawBoss.Transformed(ShapeTransform.CreateTranslation(4,4,10));using var source=box.Fuse(boss);var faces=source.GetFaces();try{using var selected=OwnedShapeSet.Create(faces.Where(f=>f.GetBoundingBox().Minimum.Z>9.99 && f.GetBoundingBox().Maximum.Z>10.01).ToArray());Assert.Equal(5,selected.Count);using var result=TopologyCollectionResult.Defeature(source,selected);using var requests=result.FacesToRemove;Assert.Equal(selected.Count,requests.Count);using var removed=selected.GetShape(0);using var modified=result.Modified(removed);using var generated=result.Generated(removed);Assert.True(result.IsDeleted(removed),"Requested boss face must be reported deleted.");using var shape=result.Shape;result.Dispose();source.Dispose();selected.Dispose();Assert.True(shape.IsValid);Assert.Equal(6,shape.FaceCount);using var copied=requests.GetShape(0);Assert.True(copied.IsValid);}finally{foreach(var f in faces)f.Dispose();}}
 [Fact]public void DefeaturingRejectsForeignFacesAndNonFaces(){using var box=ShapeFactory.CreateBox(10,10,10);using var foreign=ShapeFactory.CreateBox(10,10,10);var faces=foreign.GetFaces();try{using var set=OwnedShapeSet.Create(faces[0]);Assert.Throws<ArgumentException>(()=>TopologyCollectionResult.Defeature(box,set));using var solid=OwnedShapeSet.Create(box);Assert.Throws<ArgumentException>(()=>TopologyCollectionResult.Defeature(box,solid));}finally{foreach(var f in faces)f.Dispose();}}
 [Fact]public void SewingCouplesAreCopiedAndSurviveSharedReceiverDisposal(){using var left=SurfaceModeling.CreateAnalyticFace(AnalyticSurfaceKind.Plane,SketchPlane.XY,new(0,2,0,2));using var right=SurfaceModeling.CreateAnalyticFace(AnalyticSurfaceKind.Plane,SketchPlane.XY,new(2,4,0,2));using var faces=OwnedShapeSet.Create(left,right);using var sewing=TopologyCollections.Sew(faces);Assert.Equal(1,sewing.NbContigousEdges());using var couple=TopologyCollections.ContigousEdgeCouple(sewing,1);Assert.Equal(2,couple.Count);Assert.Throws<ArgumentException>(()=>TopologyCollections.ContigousEdgeCouple(sewing,0));Assert.Throws<ArgumentException>(()=>TopologyCollections.ContigousEdgeCouple(sewing,2));sewing.Dispose();faces.Dispose();left.Dispose();right.Dispose();using var edge=couple.GetShape(0);Assert.Equal(ShapeKind.Edge,edge.Kind);Assert.True(edge.IsValid);}
 [Fact]public void UnificationKeepsOnlyExactMemberEdgesOrVertices(){using var box=ShapeFactory.CreateBox(2,3,4);var edges=box.GetSubShapes(ShapeKind.Edge);try{using var keep=OwnedShapeSet.Create(edges[0],edges[0]);using var unified=TopologyCollections.Unify(box,keep);Assert.True(unified.IsValid);using var foreign=ShapeFactory.CreateEdge(new(0,0,0),new(2,0,0));using var wrong=OwnedShapeSet.Create(foreign);Assert.Throws<ArgumentException>(()=>TopologyCollections.Unify(box,wrong));using var wrongKind=OwnedShapeSet.Create(box);Assert.Throws<ArgumentException>(()=>TopologyCollections.Unify(box,wrongKind));}finally{foreach(var e in edges)e.Dispose();}}
 internal static void WithFile(Action<ExchangeCollectionSession> action,ExchangeCollectionFormat format=ExchangeCollectionFormat.Step){string path=Path.Combine(Path.GetTempPath(),"OcctSharp.AITest."+Guid.NewGuid().ToString("N")+(format==ExchangeCollectionFormat.Step?".step":".iges"));using var box=ShapeFactory.CreateBox(2,3,4);try{if(format==ExchangeCollectionFormat.Step)ShapeExchange.WriteStep(box,path);else ShapeExchange.WriteIges(box,path);using var session=ExchangeCollectionSession.Read(path,format);action(session);}finally{File.Delete(path);}}
 [Theory][InlineData(ExchangeCollectionFormat.Step)][InlineData(ExchangeCollectionFormat.Iges)]public void ConcreteFilesPreserveModelIndicesDynamicTypesAndSnapshotLifetime(ExchangeCollectionFormat format)=>WithFile(session=>{using var entities=session.Entities;Assert.True(entities.Count>0);using var first=entities.GetEntity(0);Assert.Equal(1,session.EntityNumber(first));Assert.StartsWith(format==ExchangeCollectionFormat.Step?"Step":"IGES",first.TypeName);using var copy=RetainedEntitySet.Create(first,first);Assert.Equal(2,copy.Count);session.Dispose();entities.Dispose();first.Dispose();using var retained=copy.GetEntity(1);Assert.NotEmpty(retained.TypeName);using var type=retained.DynamicType();Assert.NotNull(type);},format);
 [Fact]public void EmptyEntityContainersAndInvalidIndicesAreGuarded(){using var empty=RetainedEntitySet.Create();Assert.Equal(0,empty.Count);Assert.Throws<ArgumentException>(()=>empty.GetEntity(0));Assert.Throws<ArgumentNullException>(()=>RetainedEntitySet.Create((StandardTransient)null!));WithFile(session=>{using var entities=session.Entities;Assert.Throws<ArgumentException>(()=>entities.GetEntity(-1));Assert.Throws<ArgumentException>(()=>entities.GetEntity(int.MaxValue));using var e=entities.GetEntity(0);e.Dispose();Assert.Throws<ObjectDisposedException>(()=>RetainedEntitySet.Create(e));});}
 [Fact]public void IteratorsHaveDetachedContainersIndependentCursorsAndRetainingValues()=>WithFile(session=>{using var set=session.Entities;using var first=RetainedEntityIterator.Create(set);using var second=RetainedEntityIterator.Create(set);Assert.Equal(set.Count,first.Count);using var expected=second.Value;first.Next();using var unchanged=second.Value;Assert.Equal(session.EntityNumber(expected),session.EntityNumber(unchanged));using var content=first.Content;set.Dispose();first.Dispose();session.Dispose();using var independent=content.GetEntity(0);Assert.NotEmpty(independent.TypeName);Assert.True(second.More);});
 [Fact]public void IteratorEmptyExhaustionDestroyAndNativeAppendSemantics()=>WithFile(session=>{using var source=session.Entities;using var entity=source.GetEntity(0);using var iter=RetainedEntityIterator.Create();Assert.Equal(0,iter.Count);Assert.False(iter.More);Assert.Throws<ArgumentException>(()=>iter.Next());Assert.Throws<ArgumentException>(()=>iter.Value);iter.AddItem(entity);iter.GetOneItem(entity);Assert.Equal(2,iter.Count);iter.Next();iter.Next();Assert.False(iter.More);Assert.Throws<ArgumentException>(()=>iter.Next());iter.Start();Assert.True(iter.More);iter.DestroyCursor();Assert.False(iter.More);using var retained=iter.Content;Assert.Equal(2,retained.Count);iter.AddList(retained);Assert.Equal(4,iter.Count);Assert.True(iter.More);});
 [Fact]public void RuntimeTypeFilteringPreservesOriginalEntityTypes()=>WithFile(session=>{using var entities=session.Entities;using var entity=entities.GetEntity(0);using var type=entity.DynamicType()!;using var iter=RetainedEntityIterator.Create(entities);int count=iter.NbTyped(type);Assert.True(count>0);using var filtered=iter.Typed(type);Assert.Equal(count,filtered.Count);iter.SelectType(type,false);Assert.Equal(entities.Count-count,iter.Count);for(int i=0;i<filtered.Count;++i){using var e=filtered.GetEntity(i);Assert.True(e.OcctIsKind(type));}entities.Dispose();iter.Dispose();Assert.Equal(count,filtered.Count);});
 [Fact]public void DirectGraphQueriesRetainModelAndRejectForeignEntities()=>WithFile(session=>{using var entities=session.Entities;using var graph=session.CreateGraph();using var e=entities.GetEntity(0);using var a=graph.GetShareds(e);using var b=graph.Shareds(e);using var c=graph.GetSharings(e);using var d=graph.Sharings(e);Assert.Equal(a.Count,b.Count);Assert.Equal(c.Count,d.Count);WithFile(other=>{using var foreignSet=other.Entities;using var foreign=foreignSet.GetEntity(0);Assert.Throws<ArgumentException>(()=>graph.Shareds(foreign));Assert.Throws<ArgumentException>(()=>session.EntityNumber(foreign));});session.Dispose();entities.Dispose();using var roots=graph.RootEntities;Assert.True(roots.Count>0);using var independent=graph.Shareds(e);});
 [Theory][InlineData(ExchangeCollectionTransfer.Reader)][InlineData(ExchangeCollectionTransfer.TransferReader)][InlineData(ExchangeCollectionTransfer.Record)]public void SingleTransferEpochHasIndependentTypedResults(ExchangeCollectionTransfer mode)=>WithFile(session=>{using var roots=session.GiveList();Assert.True(roots.Count>0);Assert.Throws<ArgumentException>(()=>session.GetStatsTransfer(roots));Assert.True(session.Transfer(roots,mode)>0);Assert.Throws<ArgumentException>(()=>session.Transfer(roots,mode));var stats=session.GetStatsTransfer(roots);Assert.True(stats.Results>0);Assert.Equal(0,stats.Failures);using var last=session.LastTransferredEntities;Assert.True(last.Count>0);using var shapes=session.ShapeResults(mode==ExchangeCollectionTransfer.Record);Assert.True(shapes.Count>0);using var references=session.EntitiesFromShapes(shapes,ExchangeShapeLookup.Mapped);Assert.True(references.Count>0);session.Dispose();using var restored=shapes.GetShape(0);Assert.True(restored.IsValid);});
 [Fact]public void UnsafeRootAndRecordedLookupModesAreRejectedBeforeTheKernel()=>WithFile(session=>{using var roots=session.GiveList();Assert.True(session.Transfer(roots,ExchangeCollectionTransfer.Record)>0);using var shapes=session.ShapeResults(true);foreach(int mode in UnsupportedLookupModes)Assert.Throws<ArgumentException>(()=>session.EntitiesFromShapes(shapes,(ExchangeShapeLookup)mode));using var mapped=session.EntitiesFromShapes(shapes);Assert.Equal(1,mapped.Count);using var empty=OwnedShapeSet.Create();using var noMatches=session.EntitiesFromShapes(empty);Assert.Equal(0,noMatches.Count);using var lookalike=ShapeFactory.CreateBox(2,3,4);using var foreign=OwnedShapeSet.Create(lookalike);using var unrelated=session.EntitiesFromShapes(foreign);Assert.Equal(0,unrelated.Count);});
 [Fact]public void TransferValidatesAllMembershipBeforeChangingTheEpoch()=>WithFile(session=>{using var roots=session.GiveList();using var e=roots.GetEntity(0);WithFile(other=>{using var foreign=other.Entities;using var wrong=foreign.GetEntity(0);using var mixed=RetainedEntitySet.Create(e,wrong);Assert.Throws<ArgumentException>(()=>session.Transfer(mixed));});using var empty=RetainedEntitySet.Create();Assert.Throws<ArgumentException>(()=>session.Transfer(empty));Assert.True(session.Transfer(roots)>0);});
 [Fact]public void NativeSelectionOverloadsAndInvalidPathInputsAreContained()=>WithFile(session=>{using var roots=session.GiveList();using var named=session.GiveList("xst-transferrable-roots");Assert.Equal(roots.Count,named.Count);using var root=roots.GetEntity(0);using var relative=session.GiveList("xst-transferrable-roots",root);using var unknown=session.GiveList("occtsharp-unknown-selection");Assert.Equal(0,unknown.Count);Assert.Throws<ArgumentException>(()=>session.GiveList("bad\0selection"));Assert.Throws<ArgumentException>(()=>ExchangeCollectionSession.Read(Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".step")));Assert.Throws<ArgumentException>(()=>ExchangeCollectionSession.Read("bad\0.step"));});
 [Fact]public void BinderInputsAndOutputsUseIndependentRetainingContainers()=>WithFile(session=>{using var entities=session.Entities;using var e=entities.GetEntity(0);using var input=RetainedEntitySet.Create(e,e);using var multiple=ExchangeCollections.CreateMultipleBinder(input);using var list=ExchangeCollections.CreateListBinder(input);using var a=ExchangeCollections.MultipleResult(multiple);using var b=ExchangeCollections.ListResult(list);using var empty=RetainedEntitySet.Create();ExchangeCollections.SetMultipleResult(multiple,empty);using var updated=ExchangeCollections.MultipleResult(multiple);Assert.Equal(0,updated.Count);multiple.Dispose();list.Dispose();input.Dispose();entities.Dispose();e.Dispose();session.Dispose();Assert.Equal(2,a.Count);Assert.Equal(2,b.Count);using var retained=a.GetEntity(0);Assert.NotEmpty(retained.TypeName);});
 [Fact]public void SequenceUtilitiesCopyInsteadOfAliasingAndKeepNativeOneBasedIndices(){using var box=ShapeFactory.CreateBox(2,3,4);using var empty=ExchangeCollections.NewShapeSequence();using var one=ExchangeCollections.AppendShape(empty,box);using var two=ExchangeCollections.AppendShape(one,box);Assert.Equal(0,empty.Count);Assert.Equal(1,one.Count);Assert.Equal(2,two.Count);using var value=ExchangeCollections.ShapeValue(two,2);Assert.True(value.IsEqual(box));Assert.Throws<ArgumentException>(()=>ExchangeCollections.ShapeValue(two,0));Assert.Throws<ArgumentException>(()=>ExchangeCollections.ShapeValue(two,3));Assert.Throws<ArgumentException>(()=>ExchangeCollections.CompoundFromSequence(empty));using var compound=ExchangeCollections.CompoundFromSequence(two);Assert.True(compound.IsValid);WithFile(session=>{using var entities=session.Entities;using var e=entities.GetEntity(0);using var noEntities=ExchangeCollections.NewEntitySequence();using var appended=ExchangeCollections.AppendEntity(noEntities,e);Assert.Equal(0,noEntities.Count);Assert.Equal(1,appended.Count);});}
