 static nint Token(object owner)=>(owner.GetType().GetField("handle",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(owner) as SafeHandle)!.DangerousGetHandle();
 [Fact]public unsafe void RawWrongStaleTokensCountsAndPartialPublicationAreGuarded(){_=OcctRuntime.Info;nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{T Export<T>(string name)where T:Delegate=>Marshal.GetDelegateForFunctionPointer<T>(NativeLibrary.GetExport(library,name));var count=Export<CountRaw>("occtsharp_shape_set_count");var wrong=Export<CountRaw>("occtsharp_entity_set_count");var release=Export<ReleaseRaw>("occtsharp_topology_collection_release");var create=Export<CreateRaw>("occtsharp_shape_set_create");var get=Export<GetRaw>("occtsharp_shape_set_get");using var box=ShapeFactory.CreateBox(1,1,1);using var set=OwnedShapeSet.Create(box);var token=Token(set);Assert.Equal(0,count(token,out int n));Assert.Equal(1,n);Assert.NotEqual(0,wrong(token,out n));Assert.Equal(0,n);release(token,1);Assert.Equal(0,count(token,out n));Assert.NotEqual(0,create(null,-1,out nint output));Assert.Equal(0,output);Assert.NotEqual(0,create(null,int.MaxValue,out output));Assert.Equal(0,output);nint* pointers=stackalloc nint[2];pointers[0]=Token(box);pointers[1]=0;Assert.NotEqual(0,create(pointers,2,out output));Assert.Equal(0,output);Assert.NotEqual(0,get(token,2,out output));Assert.Equal(0,output);set.Dispose();Assert.NotEqual(0,count(token,out n));Assert.Equal(0,n);Assert.NotEqual(0,get(token,0,out output));Assert.Equal(0,output);var stats=Export<StatsRaw>("occtsharp_exchange_stats");int sentinel=123;Assert.NotEqual(0,stats(0,0,&sentinel,1));Assert.Equal(123,sentinel);}finally{NativeLibrary.Free(library);}}
 [Fact]public void CollectionDisposeRacesFinishWithCopiesOrManagedDisposedErrors(){using var box=ShapeFactory.CreateBox(1,1,1);for(int attempt=0;attempt<40;++attempt){using var set=OwnedShapeSet.Create(box);var errors=new System.Collections.Concurrent.ConcurrentQueue<Exception>();Parallel.For(0,12,i=>{try{if(i==0)set.Dispose();else{using var copy=set.GetShape(0);Assert.True(copy.IsValid);}}catch(ObjectDisposedException){}catch(Exception e){errors.Enqueue(e);}});Assert.Empty(errors);}}
